const terminalRecordings = `-- name: TerminalRecordings :many
SELECT organization_id, project_id, workspace_id, id, relay_session_id, stream_id, principal_id, subject, isolation, support_reason, started_at, finished_at, terminal_cols, terminal_rows, cast_object_key, cast_sha256, cast_bytes, cast_content_bytes, truncated, revision, updated_at FROM workspace_terminal_recordings WHERE organization_id=$1 AND project_id=$2 AND workspace_id=$3 AND id>$4 ORDER BY id LIMIT $5
`

type TerminalRecordingsParams struct {
	OrganizationID tracker.OrganizationID
	ProjectID      tracker.ProjectID
	WorkspaceID    string
	ID             string
	Limit          int32
}

func (q *Queries) TerminalRecordings(ctx context.Context, arg TerminalRecordingsParams) ([]WorkspaceTerminalRecording, error) {
	rows, err := q.db.Query(ctx, terminalRecordings,
		arg.OrganizationID,
		arg.ProjectID,
		arg.WorkspaceID,
		arg.ID,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WorkspaceTerminalRecording{}
	for rows.Next() {
		var i WorkspaceTerminalRecording
		if err := rows.Scan(
			&i.OrganizationID,
			&i.ProjectID,
			&i.WorkspaceID,
			&i.ID,
			&i.RelaySessionID,
			&i.StreamID,
			&i.PrincipalID,
			&i.Subject,
			&i.Isolation,
			&i.SupportReason,
			&i.StartedAt,
			&i.FinishedAt,
			&i.TerminalCols,
			&i.TerminalRows,
			&i.CastObjectKey,
			&i.CastSha256,
			&i.CastBytes,
			&i.CastContentBytes,
			&i.Truncated,
			&i.Revision,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
